// Dependency-free ledger reducer.
//
// The reducer accepts either a JSONL string or an iterable of event records.
// It validates every record, removes exact duplicate ids, rejects conflicting
// ids, and accumulates balances with BigInt so that cents are never rounded.

export class LedgerError extends Error {
  constructor(message, options = {}) {
    super(message);
    this.name = 'LedgerError';
    this.code = options.code ?? 'INVALID_LEDGER_INPUT';
    if (options.line !== undefined) this.line = options.line;
  }
}

/** Compare two strings by Unicode code point (not UTF-16 code unit). */
export function compareByCodePoint(a, b) {
  const left = Array.from(a);
  const right = Array.from(b);
  const length = Math.min(left.length, right.length);
  for (let i = 0; i < length; i += 1) {
    const diff = left[i].codePointAt(0) - right[i].codePointAt(0);
    if (diff !== 0) return diff;
  }
  return left.length - right.length;
}

function normalizeEvent(value, line) {
  const where = line === undefined ? '' : ` at line ${line}`;

  if (value === null || typeof value !== 'object' || Array.isArray(value)) {
    throw new LedgerError(`Event${where} must be a JSON object`, { line });
  }

  const { id, account, cents, kind } = value;

  if (typeof id !== 'string' || id.length === 0) {
    throw new LedgerError(`Event${where} has an invalid id (expected a nonempty string)`, { line });
  }
  if (typeof account !== 'string' || account.length === 0) {
    throw new LedgerError(`Event${where} has an invalid account (expected a nonempty string)`, { line });
  }
  if (typeof cents !== 'number' || !Number.isSafeInteger(cents) || cents < 0) {
    throw new LedgerError(
      `Event${where} has an invalid cents value (expected a nonnegative safe integer)`,
      { line },
    );
  }
  if (kind !== 'credit' && kind !== 'debit') {
    throw new LedgerError(`Event${where} has an invalid kind (expected "credit" or "debit")`, { line });
  }

  return Object.freeze({ id, account, cents, kind });
}

function sameLedgerRecord(a, b) {
  return a.id === b.id
    && a.account === b.account
    && a.cents === b.cents
    && a.kind === b.kind;
}

function* recordsFromString(text) {
  if (typeof text !== 'string') {
    throw new LedgerError('JSONL input must be a string');
  }

  // A UTF-8 BOM is only special at the very beginning of a file.
  const source = text.startsWith('\uFEFF') ? text.slice(1) : text;
  const lines = source.split(/\r\n|\n|\r/);

  for (let index = 0; index < lines.length; index += 1) {
    const line = lines[index];
    if (line.trim() === '') continue;

    let parsed;
    try {
      parsed = JSON.parse(line);
    } catch {
      throw new LedgerError(`Malformed JSON at line ${index + 1}`, {
        code: 'MALFORMED_JSON',
        line: index + 1,
      });
    }

    yield normalizeEvent(parsed, index + 1);
  }
}

/**
 * Parse and validate JSONL into event records, retaining line information.
 * Exported because the CLI needs the same exact validation path as the reducer.
 */
export function parseJsonl(text) {
  return Array.from(recordsFromString(text));
}

function toOutputInteger(value) {
  const min = BigInt(Number.MIN_SAFE_INTEGER);
  const max = BigInt(Number.MAX_SAFE_INTEGER);
  return value >= min && value <= max ? Number(value) : value;
}

/**
 * Reduce ledger events.
 *
 * @param {string|Iterable<object>} input JSONL text or an iterable of events.
 * @param {{account?: string}|string} [options] Optional account filter.
 * @returns {{uniqueEvents: number, duplicateEvents: number,
 *            accounts: Array<{account: string, balanceCents: number|bigint}>,
 *            netCents: number|bigint}}
 *
 * Values that are safe integers are returned as numbers. A balance or net that
 * cannot be represented exactly as a JS safe integer is returned as a BigInt so
 * that no precision is silently lost.
 */
export function reduceLedger(input, options = {}) {
  const filter = typeof options === 'string'
    ? options
    : options?.account;

  if (filter !== undefined && typeof filter !== 'string') {
    throw new LedgerError('Account filter must be a string');
  }

  const records = typeof input === 'string'
    ? recordsFromString(input)
    : (() => {
        if (input === null || typeof input !== 'object' || typeof input[Symbol.iterator] !== 'function') {
          throw new LedgerError('Ledger input must be JSONL text or an iterable of events');
        }
        return (function* iterate() {
          let index = 0;
          for (const value of input) {
            index += 1;
            yield normalizeEvent(value, index);
          }
        })();
      })();

  const seen = new Map();
  const balances = new Map();
  let uniqueEvents = 0;
  let duplicateEvents = 0;

  for (const record of records) {
    const previous = seen.get(record.id);

    if (previous !== undefined) {
      if (!sameLedgerRecord(previous, record)) {
        throw new LedgerError(
          `Conflicting records share id ${JSON.stringify(record.id)}`,
          { code: 'CONFLICTING_ID' },
        );
      }
      duplicateEvents += 1;
      continue;
    }

    seen.set(record.id, record);
    uniqueEvents += 1;

    const current = balances.get(record.account) ?? 0n;
    const amount = BigInt(record.cents);
    balances.set(
      record.account,
      record.kind === 'credit' ? current + amount : current - amount,
    );
  }

  const accountNames = Array.from(balances.keys())
    .filter((account) => filter === undefined || account === filter)
    .sort(compareByCodePoint);

  let net = 0n;
  const accounts = accountNames.map((account) => {
    const balance = balances.get(account);
    net += balance;
    return { account, balanceCents: toOutputInteger(balance) };
  });

  return {
    uniqueEvents,
    duplicateEvents,
    accounts,
    netCents: toOutputInteger(net),
  };
}

/** Aliases make the reducer convenient to import under common names. */
export const reduce = reduceLedger;
export const reduceEvents = reduceLedger;
export const reducer = reduceLedger;

export default reduceLedger;

function integerJson(value) {
  if (typeof value === 'bigint') return value.toString();
  if (typeof value === 'number' && Number.isFinite(value)) return String(value);
  throw new LedgerError('Ledger result contains a non-integer value');
}

/** Serialize a reducer result to the exact report JSON shape. */
export function formatReport(report) {
  const accounts = report.accounts
    .map(({ account, balanceCents }) => (
      `{"account":${JSON.stringify(account)},"balanceCents":${integerJson(balanceCents)}}`
    ))
    .join(',');

  return `{"uniqueEvents":${integerJson(report.uniqueEvents)},`
    + `"duplicateEvents":${integerJson(report.duplicateEvents)},`
    + `"accounts":[${accounts}],`
    + `"netCents":${integerJson(report.netCents)}}\n`;
}

#!/usr/bin/env node
// CLI for the dependency-free ledger reducer.

import {
  closeSync,
  fsyncSync,
  mkdirSync,
  openSync,
  readFileSync,
  renameSync,
  unlinkSync,
  writeFileSync,
} from 'node:fs';
import { basename, dirname, resolve } from 'node:path';
import { pathToFileURL } from 'node:url';
import { formatReport, LedgerError, reduceLedger } from './ledger.mjs';

const USAGE = 'usage: node reconcile.mjs INPUT OUTPUT [--account NAME]';

export function parseArgs(argv) {
  const positional = [];
  let account;
  let endOfOptions = false;

  for (let i = 0; i < argv.length; i += 1) {
    const arg = argv[i];

    if (!endOfOptions && arg === '--') {
      endOfOptions = true;
      continue;
    }

    if (!endOfOptions && arg === '--account') {
      if (i + 1 >= argv.length) {
        throw new LedgerError('--account requires a value', { code: 'USAGE' });
      }
      account = argv[i + 1];
      i += 1;
      continue;
    }

    if (!endOfOptions && arg.startsWith('--account=')) {
      account = arg.slice('--account='.length);
      continue;
    }

    if (!endOfOptions && arg.startsWith('-') && arg !== '-') {
      throw new LedgerError(`Unknown option: ${arg}`, { code: 'USAGE' });
    }

    positional.push(arg);
  }

  if (positional.length !== 2) {
    throw new LedgerError(USAGE, { code: 'USAGE' });
  }

  return { input: positional[0], output: positional[1], account };
}

function readUtf8File(filePath) {
  const bytes = readFileSync(filePath);
  try {
    return new TextDecoder('utf-8', { fatal: true }).decode(bytes);
  } catch {
    throw new LedgerError(`Input is not valid UTF-8: ${filePath}`, {
      code: 'INVALID_UTF8',
    });
  }
}

/**
 * Write a file atomically: the destination is only replaced after the complete
 * new content has been written and flushed to a temporary file in the same
 * directory. A failure leaves any existing destination untouched.
 */
export function writeFileAtomic(destination, content) {
  const target = resolve(destination);
  const directory = dirname(target);
  mkdirSync(directory, { recursive: true });

  const temporary = resolve(
    directory,
    `.${basename(target)}.${process.pid}.${Date.now()}.${Math.random().toString(16).slice(2)}.tmp`,
  );

  let fd;
  try {
    fd = openSync(temporary, 'wx', 0o666);
    writeFileSync(fd, content, { encoding: 'utf8' });
    fsyncSync(fd);
    closeSync(fd);
    fd = undefined;
    renameSync(temporary, target);
  } catch (error) {
    if (fd !== undefined) {
      try { closeSync(fd); } catch { /* best effort */ }
    }
    try { unlinkSync(temporary); } catch { /* best effort */ }
    throw error;
  }
}

export function runCli(argv) {
  const { input, output, account } = parseArgs(argv);
  const text = readUtf8File(input);
  const report = reduceLedger(text, account === undefined ? {} : { account });
  writeFileAtomic(output, formatReport(report));
}

function isMainModule() {
  if (process.argv[1] === undefined) return false;
  try {
    return import.meta.url === pathToFileURL(resolve(process.argv[1])).href;
  } catch {
    return false;
  }
}

if (isMainModule()) {
  try {
    runCli(process.argv.slice(2));
  } catch (error) {
    const message = error instanceof Error ? error.message : String(error);
    console.error(`reconcile: ${message}`);
    process.exitCode = 1;
  }
}

import test, { after } from 'node:test';
import assert from 'node:assert/strict';
import { spawnSync } from 'node:child_process';
import {
  mkdtempSync,
  mkdirSync,
  readFileSync,
  rmSync,
  writeFileSync,
} from 'node:fs';
import { tmpdir } from 'node:os';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

import reduceLedger, {
  compareByCodePoint,
  formatReport,
  LedgerError,
  parseJsonl,
  reduce,
  reduceEvents,
  reducer,
} from './ledger.mjs';

const here = dirname(fileURLToPath(import.meta.url));
const cliPath = join(here, 'reconcile.mjs');
const root = mkdtempSync(join(tmpdir(), 'ledger-tests-'));
let directoryCounter = 0;
let fileCounter = 0;

after(() => {
  rmSync(root, { recursive: true, force: true });
});

function testDirectory() {
  directoryCounter += 1;
  const directory = join(root, `case-${directoryCounter}`);
  mkdirSync(directory, { recursive: true });
  return directory;
}

function writeInput(content) {
  fileCounter += 1;
  const directory = testDirectory();
  const input = join(directory, `input-${fileCounter}.jsonl`);
  writeFileSync(input, content);
  return { directory, input };
}

function runCli(args) {
  return spawnSync(process.execPath, [cliPath, ...args], { encoding: 'utf8' });
}

function event(id, account, cents, kind) {
  return { id, account, cents, kind };
}

function jsonl(...events) {
  return `${events.map((item) => JSON.stringify(item)).join('\n')}\n`;
}

test('exports the reducer under its documented and convenient names', () => {
  assert.equal(reduce, reduceLedger);
  assert.equal(reduceEvents, reduceLedger);
  assert.equal(reducer, reduceLedger);
});

test('deduplicates identical ids and counts only unique events in balances', () => {
  const report = reduceLedger([
    event('a', 'alpha', 100, 'credit'),
    event('b', 'alpha', 30, 'debit'),
    event('a', 'alpha', 100, 'credit'),
    event('a', 'alpha', 100, 'credit'),
    event('c', 'beta', 7, 'credit'),
  ]);

  assert.equal(report.uniqueEvents, 3);
  assert.equal(report.duplicateEvents, 2);
  assert.deepEqual(report.accounts, [
    { account: 'alpha', balanceCents: 70 },
    { account: 'beta', balanceCents: 7 },
  ]);
  assert.equal(report.netCents, 77);
});

test('rejects conflicting records that share an id', () => {
  assert.throws(
    () => reduceLedger([
      event('same', 'alpha', 10, 'credit'),
      event('same', 'alpha', 11, 'credit'),
    ]),
    (error) => error instanceof LedgerError && error.code === 'CONFLICTING_ID',
  );

  assert.throws(
    () => reduceLedger([
      event('same', 'alpha', 10, 'credit'),
      event('same', 'alpha', 10, 'debit'),
    ]),
    (error) => error instanceof LedgerError && error.code === 'CONFLICTING_ID',
  );
});

test('rejects a conflict even when its account would be filtered out', () => {
  assert.throws(
    () => reduceLedger([
      event('ok', 'alpha', 10, 'credit'),
      event('bad', 'beta', 1, 'credit'),
      event('bad', 'beta', 2, 'credit'),
    ], { account: 'alpha' }),
    (error) => error instanceof LedgerError && error.code === 'CONFLICTING_ID',
  );
});

test('uses exact integer arithmetic and preserves unsafe sums as BigInt', () => {
  const max = Number.MAX_SAFE_INTEGER;

  const exactSafe = reduceLedger([
    event('credit', 'a', max, 'credit'),
    event('debit', 'a', 1, 'debit'),
  ]);
  assert.equal(exactSafe.netCents, max - 1);
  assert.equal(exactSafe.accounts[0].balanceCents, max - 1);

  const beyondSafe = reduceLedger([
    event('one', 'a', max, 'credit'),
    event('two', 'a', max, 'credit'),
    event('three', 'a', 1, 'credit'),
  ]);
  assert.equal(beyondSafe.netCents, 18014398509481983n);
  assert.equal(beyondSafe.accounts[0].balanceCents, 18014398509481983n);

  const exactText = formatReport(beyondSafe);
  assert.match(exactText, /"balanceCents":18014398509481983\}/);
  assert.match(exactText, /"netCents":18014398509481983\}/);
});

test('sorts accounts by Unicode code point, not UTF-16 code unit', () => {
  assert.ok('\uE000' < '\u{10000}'); // JS default sort gets this wrong.
  assert.ok(compareByCodePoint('\uE000', '\u{10000}') < 0);

  const names = ['\u{10000}', '账户甲', 'a', '\uE000', 'é', 'Z'];
  const report = reduceLedger(names.map((name, index) => (
    event(`id-${index}`, name, index + 1, 'credit')
  )));

  assert.deepEqual(
    report.accounts.map(({ account }) => account),
    ['Z', 'a', 'é', '账户甲', '\uE000', '\u{10000}'],
  );
});

test('filters accounts and net but keeps global event counts', () => {
  const report = reduceLedger([
    event('a', 'alpha', 100, 'credit'),
    event('b', 'beta', 40, 'debit'),
    event('c', 'beta', 5, 'credit'),
    event('d', 'gamma', 9, 'credit'),
    event('a', 'alpha', 100, 'credit'),
  ], { account: 'beta' });

  assert.equal(report.uniqueEvents, 4);
  assert.equal(report.duplicateEvents, 1);
  assert.deepEqual(report.accounts, [{ account: 'beta', balanceCents: -35 }]);
  assert.equal(report.netCents, -35);

  const missing = reduceLedger([
    event('a', 'alpha', 100, 'credit'),
  ], { account: 'nobody' });
  assert.equal(missing.uniqueEvents, 1);
  assert.deepEqual(missing.accounts, []);
  assert.equal(missing.netCents, 0);
});

test('parses BOM, CRLF, and blank or whitespace-only lines', () => {
  const text = `\uFEFF${JSON.stringify(event('a', 'alpha', 10, 'credit'))}\r\n`
    + '\r\n'
    + '   \t  \n'
    + `${JSON.stringify(event('b', 'beta', 2, 'debit'))}\r\n`;

  const report = reduceLedger(text);
  assert.equal(report.uniqueEvents, 2);
  assert.equal(report.netCents, 8);
  assert.equal(parseJsonl(text).length, 2);
});

test('CLI writes the exact report shape and creates parent directories', () => {
  const { directory, input } = writeInput(jsonl(
    event('a', '账户甲', 1000, 'credit'),
    event('b', 'alpha', 250, 'debit'),
    event('a', '账户甲', 1000, 'credit'),
  ));
  const output = join(directory, 'nested', 'deeper', 'report.json');

  const result = runCli([input, output]);
  assert.equal(result.status, 0, result.stderr);

  const text = readFileSync(output, 'utf8');
  assert.match(text, /^\{.*\}\n$/s);
  const report = JSON.parse(text);
  assert.deepEqual(Object.keys(report), [
    'uniqueEvents',
    'duplicateEvents',
    'accounts',
    'netCents',
  ]);
  assert.deepEqual(report, {
    uniqueEvents: 2,
    duplicateEvents: 1,
    accounts: [
      { account: 'alpha', balanceCents: -250 },
      { account: '账户甲', balanceCents: 1000 },
    ],
    netCents: 750,
  });
});

test('CLI --account filters accounts and net without changing event counts', () => {
  const { directory, input } = writeInput(jsonl(
    event('a', 'alpha', 100, 'credit'),
    event('b', 'beta', 60, 'credit'),
    event('c', 'beta', 10, 'debit'),
    event('b', 'beta', 60, 'credit'),
  ));
  const output = join(directory, 'report.json');

  const result = runCli([input, output, '--account', 'beta']);
  assert.equal(result.status, 0, result.stderr);
  assert.deepEqual(JSON.parse(readFileSync(output, 'utf8')), {
    uniqueEvents: 3,
    duplicateEvents: 1,
    accounts: [{ account: 'beta', balanceCents: 50 }],
    netCents: 50,
  });

  const equalsForm = runCli([input, join(directory, 'report-equals.json'), '--account=alpha']);
  assert.equal(equalsForm.status, 0, equalsForm.stderr);
  assert.deepEqual(
    JSON.parse(readFileSync(join(directory, 'report-equals.json'), 'utf8')).accounts,
    [{ account: 'alpha', balanceCents: 100 }],
  );
});

test('CLI reports exact decimal values for sums beyond safe integers', () => {
  const max = Number.MAX_SAFE_INTEGER;
  const { directory, input } = writeInput(jsonl(
    event('one', 'huge', max, 'credit'),
    event('two', 'huge', max, 'credit'),
    event('three', 'huge', 1, 'credit'),
  ));
  const output = join(directory, 'report.json');

  const result = runCli([input, output]);
  assert.equal(result.status, 0, result.stderr);

  const text = readFileSync(output, 'utf8');
  assert.match(text, /"balanceCents":18014398509481983\}/);
  assert.match(text, /"netCents":18014398509481983\}/);
});

test('invalid inputs fail with nonzero exit and preserve existing output', async (t) => {
  const invalidCases = {
    'malformed JSON': '{"id":"a","account":"x","cents":1,"kind":"credit"}\n{oops\n',
    'negative cents': jsonl(event('a', 'x', -1, 'credit')),
    'fractional cents': '{"id":"a","account":"x","cents":1.5,"kind":"credit"}\n',
    'string cents': '{"id":"a","account":"x","cents":"1","kind":"credit"}\n',
    'unsafe cents': '{"id":"a","account":"x","cents":9007199254740992,"kind":"credit"}\n',
    'empty id': jsonl(event('', 'x', 1, 'credit')),
    'empty account': jsonl(event('a', '', 1, 'credit')),
    'invalid kind': jsonl(event('a', 'x', 1, 'transfer')),
    'null record': 'null\n',
    'array record': '[]\n',
    'missing fields': '{"id":"a"}\n',
    'conflicting duplicate': jsonl(
      event('same', 'x', 1, 'credit'),
      event('same', 'x', 2, 'credit'),
    ),
  };

  for (const [name, content] of Object.entries(invalidCases)) {
    await t.test(name, () => {
      const { directory, input } = writeInput(content);
      const output = join(directory, 'report.json');
      writeFileSync(output, 'ORIGINAL CONTENT\n');

      const result = runCli([input, output]);
      assert.notEqual(result.status, 0, `expected failure for ${name}`);
      assert.match(result.stderr, /reconcile:/);
      assert.equal(readFileSync(output, 'utf8'), 'ORIGINAL CONTENT\n');
    });
  }
});

test('invalid UTF-8 fails without replacing output', () => {
  const directory = testDirectory();
  const input = join(directory, 'bad.jsonl');
  const output = join(directory, 'report.json');
  writeFileSync(input, Buffer.from([0x7b, 0x22, 0xff, 0x22, 0x7d]));
  writeFileSync(output, 'KEEP\n');

  const result = runCli([input, output]);
  assert.notEqual(result.status, 0);
  assert.match(result.stderr, /UTF-8/);
  assert.equal(readFileSync(output, 'utf8'), 'KEEP\n');
});

test('a missing input fails without replacing output', () => {
  const directory = testDirectory();
  const output = join(directory, 'report.json');
  writeFileSync(output, 'KEEP\n');

  const result = runCli([join(directory, 'does-not-exist.jsonl'), output]);
  assert.notEqual(result.status, 0);
  assert.equal(readFileSync(output, 'utf8'), 'KEEP\n');
});

test('a valid run replaces an existing output only after full validation', () => {
  const { directory, input } = writeInput(jsonl(
    event('a', 'alpha', 10, 'credit'),
  ));
  const output = join(directory, 'report.json');
  writeFileSync(output, 'OLD\n');

  const result = runCli([input, output]);
  assert.equal(result.status, 0, result.stderr);
  assert.deepEqual(JSON.parse(readFileSync(output, 'utf8')), {
    uniqueEvents: 1,
    duplicateEvents: 0,
    accounts: [{ account: 'alpha', balanceCents: 10 }],
    netCents: 10,
  });
});

test('CLI rejects bad usage and unknown options', () => {
  const noArgs = runCli([]);
  assert.notEqual(noArgs.status, 0);
  assert.match(noArgs.stderr, /usage:/i);

  const missingAccount = runCli(['in.jsonl', 'out.json', '--account']);
  assert.notEqual(missingAccount.status, 0);
  assert.match(missingAccount.stderr, /--account requires a value/);

  const unknown = runCli(['in.jsonl', 'out.json', '--bogus']);
  assert.notEqual(unknown.status, 0);
  assert.match(unknown.stderr, /Unknown option/);
});

test('CLI can safely use the input path as the output path', () => {
  const { input } = writeInput(jsonl(
    event('a', 'alpha', 15, 'credit'),
    event('b', 'alpha', 5, 'debit'),
  ));

  const result = runCli([input, input]);
  assert.equal(result.status, 0, result.stderr);
  assert.deepEqual(JSON.parse(readFileSync(input, 'utf8')), {
    uniqueEvents: 2,
    duplicateEvents: 0,
    accounts: [{ account: 'alpha', balanceCents: 10 }],
    netCents: 10,
  });
});

