node --input-type=module - <<'JS'
import { readFileSync } from 'node:fs';
const lines = readFileSync('/external/订单 数据.jsonl', 'utf8').split(/\r\n|\n|\r/);
const seen = new Map();
const bal = new Map();
let dup = 0;
for (const line of lines) {
  if (!line.trim()) continue;
  const e = JSON.parse(line);
  const r = JSON.stringify([e.id, e.account, e.cents, e.kind]);
  const prev = seen.get(e.id);
  if (prev !== undefined) {
    if (prev !== r) throw new Error('conflict');
    dup += 1;
    continue;
  }
  seen.set(e.id, r);
  bal.set(e.account, (bal.get(e.account) ?? 0n) + (e.kind === 'credit' ? BigInt(e.cents) : -BigInt(e.cents)));
}
const cmp = (a, b) => {
