import { mkdtempSync, mkdirSync, writeFileSync, readFileSync, rmSync } from 'node:fs';
import { join } from 'node:path';
import { tmpdir } from 'node:os';
import { runWatch, formatStreamReport } from './watch.mjs';

const root = mkdtempSync(join(tmpdir(), 'watch-synthetic-'));
const inbox = join(root, 'inbox');
const out = join(root, 'out');
mkdirSync(inbox, { recursive: true });
const sleep = (ms) => new Promise(r => setTimeout(r, ms));
const ev = (id, account, cents, kind) => JSON.stringify({ id, account, cents, kind }) + '\n';
const running = runWatch({ inbox, outDir: out, pollMs: 10 });
await sleep(40);
writeFileSync(join(inbox, 'batch-02.jsonl'), ev('b', 'beta', 20, 'credit'));
await sleep(40);
writeFileSync(join(inbox, 'batch-01.jsonl'), ev('a', 'alpha', 10, 'credit'));
await sleep(40);
writeFileSync(join(inbox, 'DONE'), 'done\n');
const entries = await running;
const stream = JSON.parse(readFileSync(join(out, 'stream.json'), 'utf8'));
const marker = JSON.parse(readFileSync(join(out, 'watch-started.json'), 'utf8'));
if (entries.length !== 2 || stream.length !== 2) throw new Error('wrong entry count');
if (stream[0].batch !== 'batch-01.jsonl' || stream[1].batch !== 'batch-02.jsonl') throw new Error('wrong order');
if (stream[0].summary.netCents !== 10 || stream[1].summary.netCents !== 20) throw new Error('wrong summaries');
if (typeof marker.at !== 'number') throw new Error('bad marker');
console.log('synthetic watch check: OK');
console.log(formatStreamReport(entries));
rmSync(root, { recursive: true, force: true });
